from collections import deque


def transform(grid):
    """Translate each 4-connected colored object upward so all top edges align."""
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x, color))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            objects.append(cells)
    if not objects:
        return [row[:] for row in grid]
    target_top = min(y for obj in objects for y, _, _ in obj)
    out = [[0] * w for _ in range(h)]
    for obj in objects:
        shift = min(y for y, _, _ in obj) - target_top
        for y, x, color in obj:
            ny = y - shift
            if out[ny][x] not in (0, color):
                raise ValueError("translated objects overlap")
            out[ny][x] = color
    return out

def transform(grid):
    # Extend a 2 marker vertically toward the matching colored edge object,
    # and extend the opposing edge object's aligned column across the grid.
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    bg = max(set(v for row in g for v in row), key=lambda x: sum(r.count(x) for r in g))
    # Find color-2 seeds, extend their columns toward the nearest non-background
    # edge marker, converting the seed to 4.
    seeds = [(r,c) for r in range(h) for c in range(w) if g[r][c] == 2]
    for r,c in seeds:
        g[r][c] = 4
        # Extend to the nearest occupied cell along its column, otherwise edge.
        for rr in range(r-1, -1, -1):
            if g[rr][c] != bg:
                break
            g[rr][c] = 2
    # Project distinctive same-color boundary objects vertically across.
    # For demo, rightmost 3 at bottom projects upward.
    for c in range(w):
        if g[h-1][c] not in (bg, 2, 4):
            color = g[h-1][c]
            for rr in range(h-2, -1, -1):
                if g[rr][c] == bg:
                    g[rr][c] = 2
    return g

def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    from collections import Counter
    bg = Counter(v for row in g for v in row).most_common(1)[0][0]

    # Side-edge bars: sparse marks adjacent to one bar draw rays to that
    # boundary, and their row mask is projected onto the opposing bar.
    def runs_at_edge(c, color):
        runs, start = [], None
        for r in range(h + 1):
            on = r < h and g[r][c] == color
            if on and start is None:
                start = r
            elif not on and start is not None:
                if r - start >= 2:
                    runs.append((start, r))
                start = None
        return runs

    edge_colors = {g[r][c] for c in (0, w-1) for r in range(h) if g[r][c] != bg}
    for color in edge_colors:
        left, right = runs_at_edge(0, color), runs_at_edge(w-1, color)
        if not left or not right:
            continue
        # Pick the edge run containing the most interior non-background marks.
        choices = []
        for side, runs in ((0, left), (w-1, right)):
            for a, b in runs:
                marks = [(r, c) for r in range(a, b) for c in range(1, w-1)
                         if g[r][c] not in (bg, color)]
                if marks:
                    choices.append((len(marks), side, a, b, marks))
        if not choices:
            continue
        _, side, a, b, marks = max(choices, key=lambda x: x[0])
        mark_colors = Counter(g[r][c] for r, c in marks)
        ink = mark_colors.most_common(1)[0][0]
        marks = [(r, c) for r, c in marks if g[r][c] == ink]
        active = {r-a for r, c in marks}
        # Rays from the marked bar terminate at the mark, which becomes 4.
        for r, c in marks:
            if side == 0:
                for x in range(1, c):
                    if g[r][x] == bg:
                        g[r][x] = ink
            else:
                for x in range(c+1, w-1):
                    if g[r][x] == bg:
                        g[r][x] = ink
            g[r][c] = 4
        # Transfer the mark-row mask to the opposite edge bar.
        other = right if side == 0 else left
        oa, ob = other[0]
        for off in active:
            rr = oa + off
            if rr >= ob:
                continue
            for x in range(1, w-1):
                if g[rr][x] == bg:
                    g[rr][x] = ink
        return g

    # Top/bottom edge pairs project a perpendicular line inward. The inner
    # (rightmost) cell of each pair selects its column; a 2 marker is an endpoint.
    def edge_pairs(row):
        vals, groups = [], []
        c = 0
        while c < w:
            v = g[row][c]
            if v == bg:
                c += 1
                continue
            start = c
            while c < w and g[row][c] == v:
                c += 1
            if c - start >= 2:
                groups.append((v, start, c))
        return groups

    top, bottom = edge_pairs(0), edge_pairs(h-1)
    if top and bottom:
        pair_color = top[0][0]
        interior = [g[r][c] for r in range(1, h-1) for c in range(w)
                    if g[r][c] != bg and g[r][c] != pair_color]
        if interior:
            ink = Counter(interior).most_common(1)[0][0]
            for groups, is_top in ((top, True), (bottom, False)):
                for color, start, end in groups:
                    if color != pair_color:
                        continue
                    col = end - 1
                    rows = range(1, h) if is_top else range(h-2, -1, -1)
                    for r in rows:
                        if g[r][col] == ink:
                            g[r][col] = 4
                            break
                        if g[r][col] == bg:
                            g[r][col] = ink
                        elif g[r][col] != color:
                            break
    return g

def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    from collections import Counter
    bg = Counter(v for row in g for v in row).most_common(1)[0][0]

    # Locate matching solid edge bars on opposite sides.
    def edge_runs(col, color):
        runs, start = [], None
        for r in range(h + 1):
            active = r < h and g[r][col] == color
            if active and start is None:
                start = r
            elif not active and start is not None:
                if r - start >= 2:
                    runs.append((start, r))
                start = None
        return runs

    candidates = []
    colors = {g[r][c] for c in (0, w-1) for r in range(h) if g[r][c] != bg}
    for color in colors:
        left, right = edge_runs(0, color), edge_runs(w-1, color)
        for L in left:
            for R in right:
                if L[1]-L[0] == R[1]-R[0]:
                    candidates.append((color, L, R))
    if not candidates:
        return g
    # Choose the pair with the most nearby interior marks on either side.
    color, L, R = max(candidates, key=lambda p: sum(
        1 for a,b in (p[1],p[2]) for r in range(a,b) for c in range(1,w-1)
        if g[r][c] not in (bg,p[0])))

    dotcolors = Counter(g[r][c] for r in range(h) for c in range(1,w-1)
                        if g[r][c] not in (bg,color))
    if not dotcolors:
        return g
    ink = dotcolors.most_common(1)[0][0]
    dots = [(r,c) for r in range(h) for c in range(1,w-1) if g[r][c] == ink]

    # Marks adjacent to either bar specify horizontal rays on their rows and
    # replicate their row offsets onto the opposing bar.
    selected = None
    for source, target, toward_right in ((L,R,True),(R,L,False)):
        a,b = source
        relevant = [(r,c) for r,c in dots if a <= r < b]
        if relevant:
            selected = (source,target,toward_right,relevant)
            break
    if selected:
        (a,b),(ta,tb),toward_right,relevant = selected
        offsets = set()
        for r,c in relevant:
            offsets.add(r-a)
            if toward_right:
                cells = range(1,c+1)
            else:
                cells = range(w-2,c-1,-1)
            for x in cells:
                if g[r][x] == bg:
                    g[r][x] = ink
            g[r][c] = 4
        for off in offsets:
            rr = ta + off
            if rr >= tb:
                continue
            for x in range(1,w-1):
                if g[rr][x] == bg:
                    g[rr][x] = ink
        return g

    # When marks align with one edge bar but lie near the opposite side,
    # extend from each mark toward its nearby boundary and transfer offsets.
    for source,target in ((R,L),(L,R)):
        a,b = source
        relevant = [(r,c) for r,c in dots if a <= r < b]
        if relevant:
            for r,c in relevant:
                # Marks close to left edge radiate right; marks close to right radiate left.
                if c <= w//2:
                    for x in range(c+1,w-1):
                        if g[r][x] == bg: g[r][x] = ink
                else:
                    for x in range(c-1,0,-1):
                        if g[r][x] == bg: g[r][x] = ink
                g[r][c] = 4
            for r,c in relevant:
                rr = target[0] + (r-a)
                if rr < target[1]:
                    for x in range(1,w-1):
                        if g[rr][x] == bg: g[rr][x] = ink
            return g

    # Top/bottom pair markers select vertical rays; a marker 2 is terminal.
    def pairs_at_edge(row):
        out=[]; c=0
        while c<w:
            v=g[row][c]
            if v==bg: c+=1; continue
            s=c
            while c<w and g[row][c]==v: c+=1
            if c-s>=2: out.append((v,s,c))
        return out
    top,bottom=pairs_at_edge(0),pairs_at_edge(h-1)
    if top and bottom:
