                    if g[r][col]==2:
                        g[r][col]=4; break
                    if g[r][col]==bg: g[r][col]=2
                    else: break
    return g

from collections import Counter

def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    bg = Counter(v for row in g for v in row).most_common(1)[0][0]

    # Opposite side-edge bars carry an offset mask. Interior markers in one
    # bar's span draw a ray to the marker and project that offset across the
    # grid from the other bar.
    def edge_runs(col, color):
        runs, start = [], None
        for r in range(h + 1):
            on = r < h and g[r][col] == color
            if on and start is None:
                start = r
            elif not on and start is not None:
                if r - start >= 2:
                    runs.append((start, r))
                start = None
        return runs

    edge_colors = {g[r][c] for c in (0, w - 1) for r in range(h)
                   if g[r][c] != bg}
    side_candidates = []
    for color in edge_colors:
        for left in edge_runs(0, color):
            for right in edge_runs(w - 1, color):
                if left[1] - left[0] == right[1] - right[0]:
                    side_candidates.append((color, left, right))
    for color, left, right in side_candidates:
        dots = [(r, c) for r in range(h) for c in range(1, w - 1)
                if g[r][c] not in (bg, color)]
        if not dots:
            continue
        ink = Counter(g[r][c] for r, c in dots).most_common(1)[0][0]
        dots = [(r, c) for r, c in dots if g[r][c] == ink]
        for source, target, from_left in ((left, right, True), (right, left, False)):
            a, b = source
            active = [(r, c) for r, c in dots if a <= r < b]
            if not active:
                continue
            offsets = set()
            for r, c in active:
                offsets.add(r - a)
                if from_left:
                    for x in range(1, c):
                        if g[r][x] == bg:
                            g[r][x] = ink
                else:
                    for x in range(c + 1, w - 1):
                        if g[r][x] == bg:
                            g[r][x] = ink
                g[r][c] = 4
            ta, tb = target
            for off in offsets:
                rr = ta + off
                if rr >= tb:
                    continue
                for x in range(w):
                    if (from_left and x == w - 1) or ((not from_left) and x == 0):
                        continue
                    g[rr][x] = ink
            return g

    # Matching pairs on the top and bottom edges select columns for vertical
    # rays. Existing markers of the ray color are endpoints, colored 4.
    def edge_pairs(row):
        pairs, c = [], 0
        while c < w:
            v = g[row][c]
            if v == bg:
                c += 1
                continue
            start = c
            while c < w and g[row][c] == v:
                c += 1
            if c - start >= 2:
                pairs.append((v, start, c))
        return pairs

    top, bottom = edge_pairs(0), edge_pairs(h - 1)
    for tp in top:
        for bp in bottom:
            if tp[0] != bp[0]:
                continue
            pair_color = tp[0]
            counts = Counter(g[r][c] for r in range(1, h - 1) for c in range(w)
                             if g[r][c] != bg and g[r][c] != pair_color)
            if not counts:
                continue
            ink = counts.most_common(1)[0][0]
            for pair, down in ((tp, True), (bp, False)):
                col = pair[2] - 1
                rows = range(1, h) if down else range(h - 2, -1, -1)
                for r in rows:
                    if g[r][col] == ink:
                        g[r][col] = 4
                        break
                    if g[r][col] == bg:
                        g[r][col] = ink
                    elif g[r][col] != pair_color:
                        break
            return g
    return g

