            if on and start is None:
                start = r
            elif not on and start is not None:
                if r - start >= 2:
                    out.append((start, r))
                start = None
        return out

    # Matching vertical edge bars define a row mask. Markers inside one bar's
    # span are joined to that bar; the same row offsets are projected from the
    # opposite bar.
    colors = {g[r][c] for r in range(h) for c in (0, w-1) if g[r][c] != bg}
    for color in colors:
        pairs = [(l, r) for l in edge_runs(0, color) for r in edge_runs(w-1, color)
                 if l[1]-l[0] == r[1]-r[0]]
        for left, right in pairs:
            dots = [(r,c) for r in range(h) for c in range(1,w-1)
                    if g[r][c] not in (bg,color)]
            if not dots:
                continue
            ink = Counter(g[r][c] for r,c in dots).most_common(1)[0][0]
            dots = [(r,c) for r,c in dots if g[r][c] == ink]
            for source, target, side in ((left,right,'L'), (right,left,'R')):
                a,b = source
                active = [(r,c) for r,c in dots if a <= r < b]
                if not active:
                    continue
                offsets = set()
                for r,c in active:
                    offsets.add(r-a)
                    if side == 'L':
                        xs = range(1,c)
                    else:
                        xs = range(w-2,c,-1)
                    for x in xs:
                        if g[r][x] == bg:
                            g[r][x] = ink
                    g[r][c] = 4
                ta,tb = target
                for off in offsets:
                    rr = ta+off
                    if rr >= tb:
                        continue
                    if source == left:
                        xs = range(0,w-1)
                    else:
                        xs = range(1,w)
                    for x in xs:
                        if g[rr][x] == bg:
                            g[rr][x] = ink
                return g

    # Paired colored markers on the top and bottom borders select columns for
    # inward rays. A matching 2 is the endpoint and is recolored 4.
    def edge_pairs(row):
        out, c = [], 0
        while c < w:
            v = g[row][c]
            if v == bg:
                c += 1
                continue
            start = c
            while c < w and g[row][c] == v:
                c += 1
            if c-start >= 2:
                out.append((v,start,c))
        return out

    top, bottom = edge_pairs(0), edge_pairs(h-1)
    if top and bottom:
        colors_inside = Counter(g[r][c] for r in range(1,h-1) for c in range(w)
                                if g[r][c] != bg and g[r][c] not in
                                {p[0] for p in top+bottom})
        if colors_inside:
            ink = colors_inside.most_common(1)[0][0]
            for pairs, downward in ((top,True),(bottom,False)):
                for color,start,end in pairs:
                    col = end-1
                    rows = range(1,h) if downward else range(h-2,-1,-1)
                    for r in rows:
                        if g[r][col] == ink:
                            g[r][col] = 4
                            break
                        if g[r][col] == bg:
                            g[r][col] = ink
                        else:
                            break
    return g

