    # priority is 5 > 4 > 8 > 2 > background.
    width = len(grid[0])
    layers = [grid[i:i + 3] for i in range(0, len(grid), 3)]
    priority = {0: 0, 2: 1, 8: 2, 4: 3, 5: 4}
    return [
        [max((layer[r][c] for layer in layers), key=lambda value: priority[value])
         for c in range(width)]
        for r in range(3)
    ]

def transform(grid):
    h, w = len(grid), len(grid[0])
    background = 0

    def dominant_nonzero(values):
        counts = {}
        for value in values:
            if value != background:
                counts[value] = counts.get(value, 0) + 1
        if not counts:
            return None, 0
        color = max(counts, key=counts.get)
        return color, counts[color]

    horizontal = []
    for r, row in enumerate(grid):
        color, count = dominant_nonzero(row)
        if color is not None and count > w / 2:
            horizontal.append((r, color))

    vertical = []
    for c in range(w):
        color, count = dominant_nonzero([grid[r][c] for r in range(h)])
        if color is not None and count > h / 2:
            vertical.append((c, color))

    out = [[background for _ in range(2 * len(vertical) + 1)]
           for _ in range(2 * len(horizontal) + 1)]
    for i, (r, color) in enumerate(horizontal):
        out[2 * i + 1] = [color for _ in out[2 * i + 1]]
    for j, (c, color) in enumerate(vertical):
        for rr in range(len(out)):
            out[rr][2 * j + 1] = color
    # Preserve the actual value where a horizontal and vertical stripe cross.
    for i, (r, _) in enumerate(horizontal):
        for j, (c, _) in enumerate(vertical):
            out[2 * i + 1][2 * j + 1] = grid[r][c]
    return out

from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 0 and (ny,nx) not in seen:
                        seen.add((ny,nx))
                        q.append((ny,nx))
            comps.append(comp)
    # In each 5-bounded partition, recolor the smallest cavity 7 and largest 8.
    # Candidate regions are zero components with a nontrivial 5-wall boundary.
    candidates = []
    for comp in comps:
        wall = set()
        for r, c in comp:
            for nr, nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 5:
                    wall.add((nr,nc))
        if wall:
            candidates.append(comp)
    out = [row[:] for row in grid]
    if len(candidates) >= 2:
        small = min(candidates, key=len)
        large = max(candidates, key=len)
        for r, c in small:
            out[r][c] = 7
        for r, c in large:
            out[r][c] = 8
    return out

