def transform(grid):
    """Overlay aligned panels: mark cells where the two values match."""
    h, w = len(grid), len(grid[0])
    for c in range(w):
        if c == w // 2 and w % 2 == 1 and len({grid[r][c] for r in range(h)}) == 1:
            left = [row[:c] for row in grid]
            right = [row[c + 1:] for row in grid]
            return [[3 if a == b else 4 for a, b in zip(x, y)]
                    for x, y in zip(left, right)]
    for r in range(h):
        if r == h // 2 and h % 2 == 1 and len(set(grid[r])) == 1:
            top, bottom = grid[:r], grid[r + 1:]
            return [[3 if a == b else 4 for a, b in zip(x, y)]
                    for x, y in zip(top, bottom)]
