from collections import Counter


def transform(grid):
    """Return the left panel's foreground pixels not covered by right-panel foreground."""
    h, w = len(grid), len(grid[0])
    for c in range(w):
        if c == w // 2 and w % 2 == 1 and len({grid[r][c] for r in range(h)}) == 1:
            left = [row[:c] for row in grid]
            right = [row[c + 1:] for row in grid]
            break
    else:
        for r in range(h):
            if r == h // 2 and h % 2 == 1 and len(set(grid[r])) == 1:
                left, right = grid[:r], grid[r + 1:]
                break
        else:
            raise ValueError('No centered full-length separator found')

    assert len(left) == len(right) and all(len(a) == len(b) for a, b in zip(left, right))
    bg_left = Counter(v for row in left for v in row).most_common(1)[0][0]
    bg_right = Counter(v for row in right for v in row).most_common(1)[0][0]
    return [[3 if a != bg_left and b == bg_right else 4
             for a, b in zip(row_a, row_b)]
            for row_a, row_b in zip(left, right)]

