def transform(grid):
    """Extend diagonal strokes outward from every adjacent non-background pair."""
    from collections import Counter
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    bg = Counter(v for row in out for v in row).most_common(1)[0][0]
    pairs = []
    for r in range(h):
        for c in range(w):
            if out[r][c] == bg:
                continue
            for dc in (-1, 1):
                rr, cc = r + 1, c + dc
                if 0 <= rr < h and 0 <= cc < w and out[rr][cc] != bg:
                    pairs.append(((r, c), (rr, cc)))
    for (r1, c1), (r2, c2) in pairs:
        for r, c, dr, dc in ((r1, c1, r1-r2, c1-c2),
                             (r2, c2, r2-r1, c2-c1)):
            color = out[r][c]
            rr, cc = r + dr, c + dc
            while 0 <= rr < h and 0 <= cc < w and out[rr][cc] == bg:
                out[rr][cc] = color
                rr += dr
                cc += dc
    return out

def transform(grid):
    """This task's diagonal-extension rule leaves unmatched singletons unchanged."""
    from collections import Counter
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    # Extend a diagonal only when adjacent cells have the same non-background color.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                r2, c2 = r + dr, c + dc
                if 0 <= r2 < h and 0 <= c2 < w and grid[r2][c2] == color:
                    rr, cc = r - dr, c - dc
                    while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == bg:
                        out[rr][cc] = color
                        rr -= dr
                        cc -= dc
                    rr, cc = r2 + dr, c2 + dc
                    while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == bg:
                        out[rr][cc] = color
                        rr += dr
                        cc += dc
    return out

