def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Identify rectangular loops and paint their interior with the new marker color.
    # Rule refined from demos: enclosed background cavities become 7.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 3: # background in test varies; candidate frame detected below
                pass
    # For every color other than the background, find rectangular bounding boxes;
    # fill only fully enclosed non-frame cells, leaving the boundary intact.
    colors = set(v for row in grid for v in row)
    bg = max(colors, key=lambda x: sum(row.count(x) for row in grid))
    for col in colors - {bg}:
        cells = [(r,c) for r in range(h) for c in range(w) if grid[r][c] == col]
        if not cells: continue
        r0,r1 = min(r for r,c in cells), max(r for r,c in cells)
        c0,c1 = min(c for r,c in cells), max(c for r,c in cells)
        # Rectangular frame: all extrema perimeter cells are frame color.
        if r1-r0 < 2 or c1-c0 < 2: continue
        if all(grid[r0][c] == col and grid[r1][c] == col for c in range(c0,c1+1)) and all(grid[r][c0] == col and grid[r][c1] == col for r in range(r0,r1+1)):
            for r in range(r0+1,r1):
                for c in range(c0+1,c1):
                    if grid[r][c] == bg:
                        out[r][c] = 7
    return out

def transform(grid):
    """Fill the interiors of rectangular outline components by parity."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = max({v for row in grid for v in row}, key=lambda v: sum(row.count(v) for row in grid))
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            # Find this 4-connected component of one outline color.
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx))
                        stack.append((yy,xx))
            r0, r1 = min(y for y,x in comp), max(y for y,x in comp)
            c0, c1 = min(x for y,x in comp), max(x for y,x in comp)
            if r1-r0 < 2 or c1-c0 < 2:
                continue
            # Only a complete rectangular frame encloses an area.
            if not (all(grid[r0][x] == color and grid[r1][x] == color for x in range(c0,c1+1)) and
