from collections import Counter, deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != background or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            grid[ny][nx] == background and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        q.append((ny, nx))
            # An interior component is filled. A component along the frame is
            # also enclosed when each run on the frame is stopped by foreground
            # at both ends (the frame completes the enclosing outline).
            border_runs = []
            for side in ('top', 'bottom', 'left', 'right'):
                if side == 'top':
                    vals = [grid[0][x] == background and (0, x) in set(comp) for x in range(w)]
                elif side == 'bottom':
                    vals = [grid[h-1][x] == background and (h-1, x) in set(comp) for x in range(w)]
                elif side == 'left':
                    vals = [grid[y][0] == background and (y, 0) in set(comp) for y in range(h)]
                else:
                    vals = [grid[y][w-1] == background and (y, w-1) in set(comp) for y in range(h)]
                i = 0
                while i < len(vals):
                    if not vals[i]:
                        i += 1
                        continue
                    j = i
                    while j + 1 < len(vals) and vals[j+1]:
                        j += 1
                    # Boundary corners are open exterior, not sealed pockets.
                    if i > 0 and j < len(vals)-1:
                        # Neighboring edge cells must be foreground.
                        border_runs.append(True)
                    else:
                        border_runs.append(False)
                    i = j + 1
            touches_border = any(y in (0, h-1) or x in (0, w-1) for y, x in comp)
            enclosed = not touches_border or (bool(border_runs) and all(border_runs))
            if enclosed:
                for y, x in comp:
                    out[y][x] = 4
    return out

