def transform(grid):
    """Restore slightly corrupted solid rectangular objects and clear stray marks."""
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    colors = set(v for row in grid for v in row) - {bg}
    proposals = []
    for color in colors:
        # A rectangle is accepted when all but at most a small fraction of its
        # cells carry its color. Objects in these tasks are solid rectangles;
        # occasional foreign pixels are corruption.
        for r0 in range(h):
            for r1 in range(r0 + 1, h):
                height = r1 - r0 + 1
                for c0 in range(w):
                    for c1 in range(c0 + 1, w):
                        width = c1 - c0 + 1
                        area = height * width
                        count = sum(grid[r][c] == color
                                    for r in range(r0, r1 + 1)
                                    for c in range(c0, c1 + 1))
                        if count / area >= 0.86:
                            proposals.append((count / area, count, area, color, r0, r1, c0, c1))
    # Resolve any overlap in favor of the best-supported rectangle.
    out = [[bg] * w for _ in range(h)]
    score = [[-1.0] * w for _ in range(h)]
    for density, count, area, color, r0, r1, c0, c1 in sorted(proposals, reverse=True):
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                if density > score[r][c]:
                    out[r][c] = color
                    score[r][c] = density
    return out

