def _components(grid, bg):
    h, w = len(grid), len(grid[0])
    seen, out = set(), []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            q, pts = deque([(r, c)]), set()
            seen.add((r, c))
            while q:
                y, x = q.popleft()
                pts.add((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if (0 <= yy < h and 0 <= xx < w and
                            (yy, xx) not in seen and grid[yy][xx] == color):
                        seen.add((yy, xx))
                        q.append((yy, xx))
            out.append((color, pts))
    return out


def _l_info(pts):
    if len(pts) < 5:
        return None
    r0, r1 = min(r for r, c in pts), max(r for r, c in pts)
    c0, c1 = min(c for r, c in pts), max(c for r, c in pts)
    for cr in (r0, r1):
        for cc in (c0, c1):
            expected = ({(cr, c) for c in range(c0, c1 + 1)} |
                        {(r, cc) for r in range(r0, r1 + 1)})
            if pts == expected:
                return cr, cc, (1 if cr == r0 else -1), (1 if cc == c0 else -1)
    return None


def transform(grid):
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    comps = _components(grid, bg)
    markers = [(len(pts), color, pts, _l_info(pts))
               for color, pts in comps if _l_info(pts) is not None]
    if not markers:
        return [row[:] for row in grid]

    # The L points to an object in the diagonally opposite open quadrant.
    # When a grid contains several L-shaped symbols, select the closest
    # marker/object pairing in that quadrant.
    pairs = []
    for _, marker_color, marker, info in markers:
        r, c, vdir, hdir = info
        for color, pts in comps:
            if color == marker_color or _l_info(pts) is not None:
                continue
            cy = sum(y for y, x in pts) / len(pts)
            cx = sum(x for y, x in pts) / len(pts)
            if (cy-r)*(-vdir) < 0 or (cx-c)*(-hdir) < 0:
                continue
            r0, r1 = min(y for y, x in pts), max(y for y, x in pts)
            c0, c1 = min(x for y, x in pts), max(x for y, x in pts)
            dy = max(r0-r, 0, r-r1)
            dx = max(c0-c, 0, c-c1)
            pairs.append((dy+dx, -len(marker), -len(pts), marker_color, pts))
    if not pairs:
        return [row[:] for row in grid]
    _, _, _, marker_color, target = min(pairs, key=lambda item: item[:3])
    out = [row[:] for row in grid]
    for y, x in target:
        out[y][x] = marker_color
    return out

