                conflicts = len(actual - mapped)
                missing = len(mapped - actual)
                # Require evidence that this row belongs to the template; tolerate
                # occasional extra marks, but prefer the best-aligned, complete pattern.
                key = (overlap, -conflicts, len(mapped), -missing)
