def transform(grid):
    """Mark a terminal background suffix after a complete/simple or repeated line."""
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        n = len(row)
        end = n
        while end and row[end - 1] == bg:
            end -= 1
        if end == n:
            continue
        runs = []
        i = 0
        while i < end:
            if row[i] == bg:
                i += 1
                continue
            j = i + 1
            while j < end and row[j] != bg:
                j += 1
            runs.append((i, j))
            i = j
        if not runs:
            continue
        tail = n - end
        # A single foreground block always extends into its trailing gap.
        qualifies = len(runs) == 1
        # Repeated/segmented strokes: a substantial final run qualifies too.
        if runs[-1][1] - runs[-1][0] >= 2:
            qualifies = True
        # Otherwise accept a repeated pattern ending in two foreground hits
        # separated by at most one background cell, when foreground exceeds tail.
        if len(runs) >= 2 and not qualifies:
            previous_end = runs[-1][0]
            gap = previous_end - runs[-2][1]
            total_fg = sum(b - a for a, b in runs)
            if gap <= 1 and total_fg > tail:
                qualifies = True
        if qualifies:
            for c in range(end, n):
                out[r][c] = 1
    return out

