def transform(grid):
    """Highlight missing non-background cells in a repeated terminal row motif."""
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        # Find the background suffix and the motif immediately preceding it.
        t = w
        while t and row[t - 1] == bg:
            t -= 1
        if t == w or t == 0:
            continue
        best = None
        for p in range(1, min(8, t // 2) + 1):
            motif = row[t - p:t]
            reps = 1
            while t - (reps + 1) * p >= 0 and row[t - (reps + 1) * p:t - reps * p] == motif:
                reps += 1
            if reps >= 2:
                best = (p, motif)
                break
        if best:
            p, motif = best
            for c in range(t, w):
                expected = motif[(c - t) % p]
                if expected != bg:
                    out[r][c] = 1
        # Some demonstrations have a multirow motif whose final foreground
        # pixel is vertically repeated even though its terminal run is one cell.
        if not best:
            c = t - 1
            same_neighbor = any(0 <= rr < h and grid[rr][c] == row[c] and grid[rr][c] != bg
                                for rr in (r - 1, r + 1))
            if same_neighbor:
                for x in range(t, w):
                    out[r][x] = 1
    return out

from collections import deque


def transform(grid):
    """Turn a row's trailing background into 1 when its last foreground pixel
    belongs to a multi-cell orthogonal component.
    """
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    sizes = {}
    # Label connected components of each non-background color. Infer the
    # background as the most frequent color in the grid.
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                rr, cc = q.popleft()
                cells.append((rr, cc))
                for nr, nc in ((rr-1, cc), (rr+1, cc), (rr, cc-1), (rr, cc+1)):
                    if (0 <= nr < h and 0 <= nc < w and
                            (nr, nc) not in seen and grid[nr][nc] == color):
                        seen.add((nr, nc))
                        q.append((nr, nc))
            size = len(cells)
            for cell in cells:
                sizes[cell] = size

    for r, row in enumerate(grid):
        c = w - 1
        while c >= 0 and row[c] == bg:
            c -= 1
        if c < 0 or c == w - 1:
            continue
        if sizes.get((r, c), 0) >= 2:
            for cc in range(c + 1, w):
                out[r][cc] = 1
    return out

