def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        t = w
        while t > 0 and row[t - 1] == bg:
            t -= 1
        if t == w:
            continue
        # A single non-background run ending at the left side of the tail is
        # extended across the whole background suffix.
        fg_runs = []
        i = 0
        while i < t:
            if row[i] == bg:
                i += 1
                continue
            j = i + 1
            while j < t and row[j] != bg:
                j += 1
            fg_runs.append((i, j))
            i = j
        if len(fg_runs) == 1:
            for c in range(t, w):
                out[r][c] = 1
            continue
        # Otherwise, continue a repeated short motif through the suffix.
        # A one-cell terminal gap is marked; for longer tails, mark only
        # motif positions that call for foreground rather than background.
        motif = None
        for p in range(1, min(8, t // 2) + 1):
            candidate = row[t-p:t]
            reps = 1
            while t - (reps + 1) * p >= 0 and row[t-(reps+1)*p:t-reps*p] == candidate:
                reps += 1
            if reps >= 2:
                motif = candidate
                break
        if motif is not None:
            for c in range(t, w):
                if w - t == 1 or motif[(c-t) % len(motif)] != bg:
                    out[r][c] = 1
    # Paired rows with a vertical repeated endpoint: color their common tail.
    for r in range(h-1):
        a, b = grid[r], grid[r+1]
        ta, tb = w, w
        while ta and a[ta-1] == bg: ta -= 1
        while tb and b[tb-1] == bg: tb -= 1
        if ta == tb and ta < w and ta > 0 and a[ta-1] == b[tb-1] != bg:
            for c in range(ta, w):
                out[r][c] = out[r+1][c] = 1
    return out

