        # Infer a period-two alternation from a long initial run and extend
        # only its foreground positions through the trailing background tail.
        fg = next((v for v in row if v != bg), None)
        if fg is None:
            continue
        phase = None
        for ph in (0, 1):
            n = 0
            for c, v in enumerate(row):
                want = fg if c % 2 == ph else bg
                if v != want:
                    break
                n += 1
            if n >= 8:
                phase = ph
                break
        if phase is None:
            continue
        t = w
        while t > 0 and row[t-1] == bg:
            t -= 1
        for c in range(t, w):
            if c % 2 == phase:
                out[r][c] = 1
    return out

