def transform(grid):
    """Extend a truncated horizontal motif; newly predicted foreground is 1."""
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        t = w
        while t and row[t - 1] == bg:
            t -= 1
        if t == w:
            continue
        # Find another row carrying the same observed ending motif, possibly
        # shifted horizontally; use it as a longer continuation template.
        best = None
        for rr, ref in enumerate(grid):
            if rr == r:
                continue
            for shift in range(-w + 1, w):
                # target column c maps to reference c+shift
                n = 0
                while t - n - 1 >= 0 and 0 <= t - n - 1 + shift < w and row[t-n-1] == ref[t-n-1+shift]:
                    n += 1
                if n >= 3 and t + shift < w:
                    score = (n, min(w, w-shift))
                    if best is None or score > best[0]:
                        best = (score, ref, shift)
        if best:
            _, ref, shift = best
            for c in range(t, w):
                rc = c + shift
                if 0 <= rc < w and ref[rc] != bg:
                    out[r][c] = 1
        else:
            # If the row itself has a repeated terminal motif, continue it.
            pbest = None
            for p in range(1, min(8, t // 2) + 1):
                motif = row[t-p:t]
                reps = 1
                while t-(reps+1)*p >= 0 and row[t-(reps+1)*p:t-reps*p] == motif:
                    reps += 1
                if reps >= 2 and (pbest is None or reps*p > pbest[0]):
                    pbest = (reps*p, p, motif)
            if pbest:
                _, p, motif = pbest
                for c in range(t, w):
                    if motif[(c-t) % p] != bg:
                        out[r][c] = 1
            else:
                for c in range(t,w):
                    out[r][c] = 1
    return out

