def transform(grid):
    """Complete the right-hand truncation of a repeated two-row motif using its peer rows."""
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    # Gather adjacent non-background row pairs, ignoring isolated cells/blank rows.
    pairs = []
    r = 0
    while r < h - 1:
        if any(v != bg for v in grid[r]) and any(v != bg for v in grid[r+1]):
            pairs.append((r, r+1))
            r += 2
        else:
            r += 1
    for a, b in pairs:
        end = w
        while end > 0 and grid[a][end-1] == bg and grid[b][end-1] == bg:
            end -= 1
        if end == w:
            continue
        # Only extend a common trailing background suffix where another peer
        # pair demonstrates foreground in both corresponding positions.
        for c in range(end, w):
            if any(x != a and y != b and grid[x][c] != bg and grid[y][c] != bg
                   for x, y in pairs):
                out[a][c] = 1
                out[b][c] = 1
    return out

